	local targetTrans = math.clamp(self.Config.Values.XRayTransparency / 100, 0, 1);
	for _, part in ipairs(self.Services.Workspace:GetDescendants()) do
		if (part:IsA("BasePart") and not part:IsA("Terrain")) then
