				for _, p in ipairs(char:GetDescendants()) do
					if p:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\11\57\95\74\4\126\203\61", "\185\73\88\44\47\84\31")) then
						if (p.Name == "HumanoidRootPart") then
							p.CanCollide = false;
						elseif ((p.Name == "Head") or p.Name:find("Torso") or p.Name:find("Leg") or p.Name:find("Arm")) then
							p.CanCollide = true;
						end
					end
				end
			end
		end
