		if not targetPart then
			local pad = self:GetVotePad(LUAOBFUSACTOR_DECRYPT_STR_0("\241\229\96\126\225\180\184\181", "\132\167\138\20\27\177\213\220")) or self:GetVotePad("VotePad2");
