Hub.SwitchTab = function(self, tabName)
	self.Config.ActiveTab = tabName;
	if self.State.SubHeaderIcon then
		self.State.SubHeaderIcon.Image = Icons[tabName] or Icons.Combat;
	end
	if self.State.SubHeaderTitle then
		self.State.SubHeaderTitle.Text = tabName;
	end
	if self.State.SearchBox then
		self.State.SearchBox.Text = "";
	end
	local activeBtnData = self.State.TabButtons[tabName];
	if (activeBtnData and self.State.TabIndicator and self.State.NavCapsule) then
		local btn = activeBtnData.Button;
		local order = activeBtnData.LayoutOrder or 1;
		local targetX = 4 + ((order - 1) * 80);
		local targetY = 3;
		if ((btn.AbsolutePosition.X > 0) and (self.State.NavCapsule.AbsolutePosition.X > 0)) then
			local relX = btn.AbsolutePosition.X - self.State.NavCapsule.AbsolutePosition.X;
			local relY = btn.AbsolutePosition.Y - self.State.NavCapsule.AbsolutePosition.Y;
			if ((relX >= 0) and (relY >= 0)) then
				targetX = relX;
				targetY = relY;
			end
		end
		self:Tween(self.State.TabIndicator, {Position=UDim2.new(0, targetX, 0, targetY),Size=UDim2.new(0, ((btn.AbsoluteSize.X > 0) and btn.AbsoluteSize.X) or 76, 0, ((btn.AbsoluteSize.Y > 0) and btn.AbsoluteSize.Y) or 24)}, 0.28, Enum.EasingStyle.Quart, Enum.EasingDirection.Out);
	end
	for name, data in pairs(self.State.TabButtons) do
		local page = self.State.Tabs[name];
		if (name == tabName) then
			page.Visible = true;
			data.Title.Font = Enum.Font.GothamBold;
			data.Button.BackgroundTransparency = 1;
			self:Tween(data.Title, {TextColor3=Color3.fromRGB(18, 18, 22)}, 0.2);
			if data.Icon then
				self:Tween(data.Icon, {ImageColor3=Color3.fromRGB(18, 18, 22)}, 0.2);
			end
		else
			page.Visible = false;
			data.Title.Font = Enum.Font.GothamMedium;
			data.Button.BackgroundTransparency = 1;
			self:Tween(data.Title, {[LUAOBFUSACTOR_DECRYPT_STR_0("\158\131\1\230\137\137\21\253\184\213", "\146\202\230\121")]=self.Theme.TextDim}, 0.2);
			if data.Icon then
				self:Tween(data.Icon, {ImageColor3=self.Theme.TextDim}, 0.2);
			end
		end
	end
	if (tabName == "Visuals") then
		if self.World.Section then
			self.World.Section.Visible = true;
			self:Tween(self.World.Section, {BackgroundTransparency=0}, 0.3);
		end
	elseif self.World.Section then
		self.World.Section.Visible = false;
	end
end;
