Hub.PlayCatalogAnimation = function(self, assetId, category)
	local char = self.Services.Players.LocalPlayer.Character;
	local hum = char and char:FindFirstChildOfClass(LUAOBFUSACTOR_DECRYPT_STR_0("\192\80\62\60\141\231\76\55", "\227\136\37\83\93"));
	if not hum then
		return;
	end
	self:StopAnimation();
	task.spawn(function()
		local realAnimId = self:ResolveAnimationId(assetId);
		local anim = Instance.new("Animation");
		anim.AnimationId = realAnimId;
		local animator = hum:FindFirstChildOfClass("Animator") or hum;
		local track = animator:LoadAnimation(anim);
		if ((category == "Animations") or (category == "Walk Styles")) then
			track.Priority = Enum.AnimationPriority.Movement;
			track.Looped = true;
			track:Play();
			self.Animations.CurrentTrack = track;
			self.Animations.EmoteTrack = nil;
		else
			track.Priority = Enum.AnimationPriority.Action4;
			track.Looped = true;
			track:Play();
			self.Animations.CurrentTrack = track;
			self.Animations.EmoteTrack = track;
		end
	end);
end;
Hub.StopAnimation = function(self)
	if self.Animations.CurrentTrack then
		pcall(function()
			self.Animations.CurrentTrack:Stop();
		end);
		self.Animations.CurrentTrack = nil;
	end
	self.Animations.EmoteTrack = nil;
	local lp = self.Services.Players.LocalPlayer;
	local char = lp.Character;
	local hum = char and char:FindFirstChildOfClass("Humanoid");
	local animator = hum and hum:FindFirstChildOfClass("Animator");
	if animator then
		for _, t in ipairs(animator:GetPlayingAnimationTracks()) do
			if ((t.Priority == Enum.AnimationPriority.Action) or (t.Priority == Enum.AnimationPriority.Action4)) then
				pcall(function()
					t:Stop();
				end);
			end
		end
	end
end;
Hub.BuildConfigTab = function(self, container)
	local leftCol, rightCol = self:CreateDualColumnPage(container);
	local menuSec = self:CreateSection(leftCol, "Interface & HUD", "Customize on-screen HUD and client hotkeys");
	self:CreateToggle(menuSec, "Watermark HUD", self.Config.Toggles.Watermark, function(v)
		self.Config.Toggles.Watermark = v;
		if self.State.Watermark then
			self.State.Watermark.Visible = v;
		end
	end);
	self:CreateKeybind(menuSec, "Toggle Menu Key", self.Config.MenuKey, function(key)
		self.Config.MenuKey = key;
	end);
	local actSec = self:CreateSection(rightCol, "Script Control", "Session management and clean exit");
	self:CreateButton(actSec, "Rejoin Current Server", function()
		pcall(function()
			self.Services.TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, self.Services.Players.LocalPlayer);
		end);
	end);
	local unloadBtn = self:CreateButton(actSec, "Unload Script (Clean Exit)", function()
		self:Unload();
	end);
	unloadBtn.TextColor3 = Color3.fromRGB(255, 90, 100);
	unloadBtn.BackgroundColor3 = Color3.fromRGB(45, 18, 24);
end;
Hub.ToggleMenu = function(self, state)
	if (state == nil) then
		state = not self.State.IsOpen;
	end
	self.State.IsOpen = state;
	local targetSize = self.State.WindowSize or UDim2.new(0, 720, 0, 500);
	if state then
		self.State.MainFrame.Visible = true;
		if self.State.Shadow then
			self.State.Shadow.Visible = true;
		end
		self:Tween(self.State.MainFrame, {Size=targetSize}, 0.25);
		if (self.State.SidePanelOpen and self.State.SidePanel) then
			self:UpdateSidePanelPosition();
			self.State.SidePanel.Visible = true;
			self:Tween(self.State.SidePanel, {BackgroundTransparency=0}, 0.2);
		end
	else
		if self.State.Shadow then
			self.State.Shadow.Visible = false;
		end
		if self.State.SidePanel then
			self.State.SidePanel.Visible = false;
		end
		if self.State.SideTooltip then
			self.State.SideTooltip.Visible = false;
		end
		local tw = self:Tween(self.State.MainFrame, {Size=UDim2.new(0, targetSize.X.Offset, 0, 0)}, 0.2);
		tw.Completed:Connect(function()
			if not self.State.IsOpen then
				self.State.MainFrame.Visible = false;
			end
		end);
	end
end;
Hub.SetupWindowDragging = function(self)
	local drag = {Dragging=false,Start=Vector3.new(0, 0, 0),Pos=UDim2.new()};
	local topbar = self.State.TopBar;
	local main = self.State.MainFrame;
	local shadow = self.State.Shadow;
	topbar.InputBegan:Connect(function(input)
		if ((input.UserInputType == Enum.UserInputType.MouseButton1) or (input.UserInputType == Enum.UserInputType.Touch)) then
			drag.Dragging = true;
			drag.Start = input.Position;
			drag.Pos = main.Position;
			input.Changed:Connect(function()
				if (input.UserInputState == Enum.UserInputState.End) then
					drag.Dragging = false;
				end
			end);
		end
	end);
	self.Services.UserInputService.InputChanged:Connect(function(input)
		if (drag.Dragging and ((input.UserInputType == Enum.UserInputType.MouseMovement) or (input.UserInputType == Enum.UserInputType.Touch))) then
			local delta = input.Position - drag.Start;
			local newPos = UDim2.new(drag.Pos.X.Scale, drag.Pos.X.Offset + delta.X, drag.Pos.Y.Scale, drag.Pos.Y.Offset + delta.Y);
			main.Position = newPos;
			if shadow then
				shadow.Position = newPos;
			end
			self:UpdateSidePanelPosition();
		end
	end);
end;
Hub.IsMouseOverGui = function(self)
	if not (self.State.Gui and self.State.Gui.Parent and self.State.Gui.Enabled) then
		return false;
	end
	local main = self.State.Main;
	if not (main and main.Visible) then
		return false;
	end
	local mouse = self.Services.Players.LocalPlayer:GetMouse();
	local mx, my = mouse.X, mouse.Y;
	local pos = main.AbsolutePosition;
	local size = main.AbsoluteSize;
	if ((mx >= pos.X) and (mx <= (pos.X + size.X)) and (my >= pos.Y) and (my <= (pos.Y + size.Y))) then
		return true;
	end
	return false;
end;
Hub.SetupKeybinds = function(self)
	self.Services.UserInputService.InputBegan:Connect(function(input, gp)
		if self.Config.IsListeningMenuKey then
			return;
		end
		if (input.KeyCode == self.Config.MenuKey) then
			self:ToggleMenu();
			return;
		end
		if self.Config.IsListeningShootKey then
			return;
		end
		if (self.Config.ShootKey and (self.Config.ShootKey ~= Enum.KeyCode.Unknown)) then
			if ((input.KeyCode == self.Config.ShootKey) or (input.UserInputType == self.Config.ShootKey)) then
				self:ShootMurderer(self.Config.Toggles.AimWallbang, self.Config.Toggles.AimPrediction);
				return;
			end
		end
		if (input.UserInputType == Enum.UserInputType.MouseButton1) then
			if gp then
				return;
			end
			if self:IsMouseOverGui() then
				return;
			end
			local char = self.Services.Players.LocalPlayer.Character;
			local gunInHand = nil;
			if char then
				for _, item in ipairs(char:GetChildren()) do
					if (item:IsA("Tool") and (item.Name:lower():find("gun") or item:FindFirstChild("Shoot") or item:FindFirstChild("ShootGun"))) then
						gunInHand = item;
						break;
					end
				end
			end
			if gunInHand then
				self:ShootGun();
			end
		end
	end);
	self.Services.UserInputService.JumpRequest:Connect(function()
		if self.Config.Toggles.InfiniteJump then
			local hum = self.Services.Players.LocalPlayer.Character and self.Services.Players.LocalPlayer.Character:FindFirstChildOfClass("Humanoid");
			if hum then
				hum:ChangeState(Enum.HumanoidStateType.Jumping);
			end
		end
	end);
end;
Hub.StartMainLoops = function(self)
	self.Services.RunService.RenderStepped:Connect(function()
		if (self.Config.Toggles.ESPRoles or self.Config.Toggles.ESPGun) then
			self:RenderESP();
		end
	end);
	task.spawn(function()
		while self.State.Gui and self.State.Gui.Parent do
			if (self.Config.Toggles.AutoShotMurderer and ((os.clock() - self.Combat.LastShot) > 0.4)) then
				self:ShootMurderer();
			end
			task.wait(0.2);
		end
	end);
	task.spawn(function()
		while self.State.Gui and self.State.Gui.Parent do
			if self.Config.Toggles.KillAll then
				self:ExecuteKillAll();
			end
			task.wait(0.2);
		end
	end);
	task.spawn(function()
		while self.State.Gui and self.State.Gui.Parent do
			if self.Config.Toggles.KillAura then
				local knife = self:FindKnife();
				local lp = self.Services.Players.LocalPlayer;
				local myRoot = self:GetRoot(lp.Character);
				if (knife and myRoot) then
					local mode = self.Config.Values.KillMode or "Classic";
					local maxDist = self.Config.Values.KillAuraDist or 18;
					for _, p in ipairs(self.Services.Players:GetPlayers()) do
						if (p ~= lp) then
							local ch = p.Character;
							local root = self:GetRoot(ch);
							local hum = ch and ch:FindFirstChildOfClass(LUAOBFUSACTOR_DECRYPT_STR_0("\113\184\5\117\87\162\1\112", "\20\57\205\104"));
							if (root and hum and (hum.Health > 0)) then
								local dist = (root.Position - myRoot.Position).Magnitude;
								if (dist <= maxDist) then
									task.spawn(function()
										if (mode == "Silent") then
											self:StabSilent(p, knife);
										else
											self:StabClassic(p, knife);
										end
									end);
								end
							end
						end
					end
				end
			end
			task.wait(0.1);
		end
	end);
	task.spawn(function()
		while self.State.Gui and self.State.Gui.Parent do
			if self.Config.Toggles.AutoKillSheriff then
				self:KillSheriff();
			end
			task.wait(0.2);
		end
	end);
	task.spawn(function()
		while self.State.Gui and self.State.Gui.Parent do
			if self.Config.Toggles.AutoGrabGun then
				self:GrabDroppedGun();
			end
			task.wait(0.25);
		end
	end);
	self.Services.RunService.Heartbeat:Connect(function()
		if self.Config.Toggles.SpeedHack then
			local lp = self.Services.Players.LocalPlayer;
			local char = lp.Character;
			local hum = char and char:FindFirstChildOfClass(LUAOBFUSACTOR_DECRYPT_STR_0("\0\190\21\184\20\85\58\44", "\83\72\203\120\217\122\58"));
			if (hum and (hum.WalkSpeed ~= self.Config.Values.WalkSpeed)) then
				hum.WalkSpeed = self.Config.Values.WalkSpeed;
			end
		end
	end);
	local wasNoClip = false;
	self.Services.RunService.Stepped:Connect(function()
		if self.Config.Toggles.NoClip then
			wasNoClip = true;
			local char = self.Services.Players.LocalPlayer.Character;
			if char then
				for _, p in ipairs(char:GetDescendants()) do
					if p:IsA("BasePart") then
						p.CanCollide = false;
					end
				end
			end
		elseif wasNoClip then
			wasNoClip = false;
			self:RestoreCollisions();
		end
	end);
	self.Services.RunService.Stepped:Connect(function()
		if self.Config.Toggles.AntiFling then
			local lp = self.Services.Players.LocalPlayer;
			for _, p in ipairs(self.Services.Players:GetPlayers()) do
				if ((p ~= lp) and p.Character) then
					for _, part in ipairs(p.Character:GetDescendants()) do
						if part:IsA("BasePart") then
							part.CanCollide = false;
						end
					end
				end
			end
		end
	end);
	self.Services.RunService.Heartbeat:Connect(function()
		if self.Config.Toggles.AntiFling then
			local lp = self.Services.Players.LocalPlayer;
			local char = lp.Character;
			local root = char and self:GetRoot(char);
			if root then
				if (root.AssemblyAngularVelocity.Magnitude > 30) then
					root.AssemblyAngularVelocity = Vector3.new(0, 0, 0);
				end
				if (root.AssemblyLinearVelocity.Magnitude > 110) then
					local vel = root.AssemblyLinearVelocity;
					root.AssemblyLinearVelocity = Vector3.new(math.clamp(vel.X, -30, 30), math.clamp(vel.Y, -40, 40), math.clamp(vel.Z, -30, 30));
				end
			end
		end
	end);
	local flingActive = false;
	self.Services.RunService.Heartbeat:Connect(function()
		if self.Config.Toggles.WalkFling then
			local lp = self.Services.Players.LocalPlayer;
			local char = lp.Character;
			local root = char and self:GetRoot(char);
			local hum = char and char:FindFirstChildOfClass("Humanoid");
			if not (root and hum and (hum.Health > 0)) then
				return;
			end
			local myPos = root.Position;
			local targetFound = false;
			if (hum.MoveDirection.Magnitude > 0.05) then
				for _, other in ipairs(self.Services.Players:GetPlayers()) do
					if ((other ~= lp) and other.Character) then
						local oRoot = other.Character:FindFirstChild("HumanoidRootPart");
						if (oRoot and ((oRoot.Position - myPos).Magnitude <= 5.5)) then
							targetFound = true;
							break;
						end
					end
				end
			end
			if targetFound then
				flingActive = true;
				hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false);
				hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false);
				root.AssemblyAngularVelocity = Vector3.new(0, 16000, 0);
				local curV = root.AssemblyLinearVelocity;
				if (curV.Y > 0) then
					root.AssemblyLinearVelocity = Vector3.new(curV.X, 0, curV.Z);
				end
			elseif flingActive then
				flingActive = false;
				root.AssemblyAngularVelocity = Vector3.new(0, 0, 0);
			end
		end
	end);
	self.Services.RunService.Stepped:Connect(function()
		if self.Config.Toggles.WalkFling then
			local lp = self.Services.Players.LocalPlayer;
			local char = lp.Character;
			local root = char and self:GetRoot(char);
			local hum = char and char:FindFirstChildOfClass("Humanoid");
			if (root and hum) then
				hum.PlatformStand = false;
				hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false);
				hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false);
				if not flingActive then
					root.AssemblyAngularVelocity = Vector3.new(0, 0, 0);
				end
			end
		end
	end);
	self.Services.RunService.Heartbeat:Connect(function()
		if (self.Animations and self.Animations.EmoteWalk and self.Animations.EmoteTrack) then
			local track = self.Animations.EmoteTrack;
			local ok, playing = pcall(function()
				return track.IsPlaying;
			end);
			if (ok and not playing) then
				pcall(function()
					if (track.Length and (track.Length > 0)) then
						track:Play();
					end
				end);
			end
		end
	end);
	self.Services.Players.LocalPlayer.CharacterAdded:Connect(function(newChar)
		self.Animations.CurrentTrack = nil;
		self.Animations.EmoteTrack = nil;
		task.wait(0.25);
		local hum = newChar:WaitForChild(LUAOBFUSACTOR_DECRYPT_STR_0("\148\252\182\162\161\178\182\184", "\223\220\137\219\195\207\221"), 3);
		if (hum and self.Config.Toggles.SpeedHack) then
			hum.WalkSpeed = self.Config.Values.WalkSpeed;
		end
		self:CloneLocalPlayerModel();
		self:ApplyWorldSettings();
		if self.Config.Toggles.LocalESP then
			self:UpdatePreviewLocalESP();
		end
		if self.SkinSystem.AutoReapply then
			for slot, rec in pairs(self.SkinSystem.Picked) do
				self:ApplySkinToDisplay(rec);
				self:ApplySkinToTool(rec);
			end
		end
	end);
	self:SetupAntiAFK();
	for k, v in pairs(self.ValuesSystem.FallbackValues) do
		self:RegisterValueEntry(k, v);
	end
	task.spawn(function()
		self:FetchValues();
		while self.State.Gui and self.State.Gui.Parent do
			task.wait(10);
			if ((os.clock() - self.ValuesSystem.LastFetch) >= self.ValuesSystem.FetchInterval) then
				self:FetchValues();
			end
		end
	end);
	task.spawn(function()
		while self.State.Gui and self.State.Gui.Parent do
			if self.Config.Toggles.ShowSkinValues then
				self:UpdateInventoryValues();
				self:UpdateTradeValues();
			end
			task.wait(0.25);
		end
	end);
	task.spawn(function()
		self:LoadSkinDatabase();
	end);
	task.spawn(function()
		local lastTime = os.clock();
		local frameCount = 0;
		local currentFps = 60;
		self.Services.RunService.RenderStepped:Connect(function()
			frameCount = frameCount + 1;
			local now = os.clock();
			if ((now - lastTime) >= 0.5) then
				currentFps = math.floor(frameCount / (now - lastTime));
				frameCount = 0;
				lastTime = now;
				if (self.State.WatermarkLabel and self.Config.Toggles.Watermark) then
					local pingMs = 45;
					pcall(function()
						local stats = game:GetService(LUAOBFUSACTOR_DECRYPT_STR_0("\32\92\94\246\63", "\76\115\40\63\130"));
						local net = stats and stats:FindFirstChild("Network");
						local sItem = net and net:FindFirstChild("ServerStatsItem");
						local pingVal = sItem and sItem:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\163\27\57\172\246\225\142\20\42", "\177\231\122\77\205\214"));
						if pingVal then
							pingMs = math.floor(pingVal:GetValue());
						end
					end);
					self.State.WatermarkLabel.Text = string.format('<font color="#FFFFFF"><b>DYNAMIC</b></font>  <font color="#444455">|</font>  MM2  <font color="#444455">|</font>  %d fps  <font color="#444455">|</font>  %d ms', currentFps, pingMs);
				end
			end
		end);
	end);
	pcall(function()
		local rep = self.Services.ReplicatedStorage;
		local remotes = rep:FindFirstChild("Remotes");
		local gp = remotes and remotes:FindFirstChild("Gameplay");
		if gp then
			for _, evName in ipairs({LUAOBFUSACTOR_DECRYPT_STR_0("\99\18\76\69\134\74\65\1", "\60\36\115\33\32\201"),"RoundEndFade",LUAOBFUSACTOR_DECRYPT_STR_0("\129\127\84\82\67\76\36\146\180\100\82\67\66", "\193\215\22\55\38\44\62\93")}) do
				local ev = gp:FindFirstChild(evName);
				if (ev and ev:IsA("RemoteEvent")) then
					local c = ev.OnClientEvent:Connect(function()
						self:StopAutoFarmTween();
					end);
					table.insert(self.State.Connections, c);
				end
			end
		end
	end);
	self:StartAutoFarmLoop();
end;
Hub.Unload = function(self)
	self:StopAutoFarmTween();
	if self.State.Connections then
		for _, c in ipairs(self.State.Connections) do
			pcall(function()
				c:Disconnect();
			end);
		end
		self.State.Connections = {};
	end
	if self.Crosshair.Connection then
		pcall(function()
			self.Crosshair.Connection:Disconnect();
		end);
		self.Crosshair.Connection = nil;
	end
	if self.Crosshair.Gui then
		pcall(function()
			self.Crosshair.Gui:Destroy();
		end);
		self.Crosshair.Gui = nil;
	end
	local lp = self.Services.Players.LocalPlayer;
	local mm2Crosshair = lp and lp:FindFirstChild("PlayerGui") and lp.PlayerGui:FindFirstChild("GameTopbar") and lp.PlayerGui.GameTopbar:FindFirstChild("Crosshair");
	if (mm2Crosshair and self.Crosshair.OriginalTransparency) then
		mm2Crosshair.ImageTransparency = self.Crosshair.OriginalTransparency;
	end
	self:StopAnimation();
	self:ClearAllESP();
	self:DisableXRay();
	if self.State.Gui then
		self.State.Gui:Destroy();
	end
end;
Hub:Init();
_G.DynamicHub = Hub;
if getgenv then
	pcall(function()
		getgenv().DynamicHub = Hub;
	end);
end
print("Welcome to Dynamic Hub");
